}
function drawTrack(){let h=horizon(),near=project(0,0,-.8),far=project(0,0,72),leftNear=project(-3.35,0,-.8),rightNear=project(3.35,0,-.8),leftFar=project(-3.35,0,72),rightFar=project(3.35,0,72);
 poly([{x:0,y:h},{x:W,y:h},rightNear,rightFar],'#172d3a');
