 // sleepers receding into distance
 for(let z=((world*1.1)%3);z<70;z+=3){let a=project(-3.2,0,z),b=project(3.2,0,z);line(a,b,z<12?'#bbc1bd':'#6d7777',Math.max(.5,project(0,0,z).s*.09))}
