function drawObstacle(o){let l=o.lane*2.08,z=o.z,sc=project(0,0,z).s;
 if(o.type==='train'){
  let hw=1.02,dep=o.depth||7,fl=project(l-hw,0,z),fr=project(l+hw,0,z),ftl=project(l-hw,2.4,z),ftr=project(l+hw,2.4,z),bl=project(l-hw,0,z+dep),br=project(l+hw,0,z+dep),btl=project(l-hw,2.4,z+dep),btr=project(l+hw,2.4,z+dep);
