  line(project(l-.92,.25,z-.02),project(l+.92,.25,z-.02),'#ffcc52',Math.max(2,sc*.09));let p=project(l,2.4,z);ctx.fillStyle='#ff5a6e';ctx.shadowColor='#ff5865';ctx.shadowBlur=sc*.2;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(2,sc*.1),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
 }else if(o.type==='barrier'){
  let a=project(l-.76,0,z),b=project(l+.76,0,z),c=project(l+.76,1.15,z),d=project(l-.76,1.15,z);poly([a,b,c,d],'#f4a64e','#ffda7c',Math.max(1,sc*.035));for(let k=-1;k<=1;k++){let x=l+k*.45;line(project(x-.12,0,z-.01),project(x+.25,1.15,z-.01),'#513344',Math.max(1,sc*.09))}let leg1=project(l-.56,0,z+.18),leg2=project(l+.56,0,z+.18);line(project(l-.56,0,z),leg1,'#85898a',Math.max(1,sc*.07));line(project(l+.56,0,z),leg2,'#85898a',Math.max(1,sc*.07));
 }else{
