 }else{
  // legs
  let leg=step*unit;rounded(-unit*.47,-unit*.87+leg,unit*.39,unit*.81,unit*.16,'#182b3c');rounded(unit*.08,-unit*.87-leg,unit*.39,unit*.81,unit*.16,'#1c3447');rounded(-unit*.52,-unit*.13+leg,unit*.49,unit*.19,unit*.08,'#f1f5ee');rounded(unit*.02,-unit*.13-leg,unit*.49,unit*.19,unit*.08,'#f1f5ee');
  // torso + arms
  rounded(-unit*.56,-unit*2.02,unit*1.12,unit*1.18,unit*.29,tint);rounded(-unit*.77,-unit*1.92+step*2,unit*.26,unit*.8,unit*.12,'#dca985');rounded(unit*.51,-unit*1.9-step*2,unit*.26,unit*.8,unit*.12,'#dca985');
  // jacket detail
