  ctx.fillStyle='#172437';ctx.beginPath();ctx.arc(-unit*.15,-unit*2.48,unit*.045,0,7);ctx.arc(unit*.14,-unit*2.48,unit*.045,0,7);ctx.fill();
 }
 ctx.restore();}
function drawParticle(p){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}

