function drawParticle(p){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function addCoins(laneN,count=5,gap=2.2,start=59){for(let i=0;i<count;i++)objects.push({kind:'coin',lane:laneN,z:start+i*gap,bob:Math.random()*6})}
function spawnPattern(){let available=[-1,0,1],pick=()=>available[Math.floor(Math.random()*3)],r=Math.random();if(r<.25){let l=pick();addCoins(l,5,2.4,64);return}if(r<.56){let l=pick(),type=Math.random()<.54?'barrier':Math.random()<.5?'beam':'train';objects.push({kind:'obstacle',type,lane:l,z:68,depth:type==='train'?7:0});let safe=available.filter(n=>n!==l)[Math.floor(Math.random()*2)];if(Math.random()<.6)addCoins(safe,4,2.5,59);return}if(r<.77){let l=pick();objects.push({kind:'obstacle',type:'train',lane:l,z:70,depth:8});let safe=available.filter(n=>n!==l);let other=safe[Math.floor(Math.random()*2)];objects.push({kind:'obstacle',type:'barrier',lane:other,z:70,depth:0});addCoins(safe[1-(safe.indexOf(other))],4,2.5,57);return}let l=pick();objects.push({kind:'obstacle',type:'beam',lane:l,z:67});if(Math.random()<.7)addCoins(available.filter(n=>n!==l)[0],5,2.2,57)}
let audioCtx=null;function beep(freq=720,duration=.08,type='sine'){if(!sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function setOverlay(which){['startScreen','pauseScreen','overScreen'].forEach(id=>$(id).classList.toggle('hidden',id!==which))}
function startRun(){state='playing';lane=0;targetLane=0;playerY=0;vy=0;sliding=0;distance=0;runCoins=0;speed=17;world=0;spawnTimer=.45;objects=[];particles=[];shake=0;for(let i=0;i<5;i++)objects.push({kind:'coin',lane:0,z:13+i*2.7,bob:i});setOverlay('');$('pauseBtn').style.visibility='visible';$('bottomline').style.display='block';$('mobileControls').style.display='flex'}
function pauseRun(){if(state==='playing'){state='paused';setOverlay('pauseScreen')}else if(state==='paused'){state='playing';last=performance.now();setOverlay('')}}
function finishRun(){if(state!=='playing')return;state='over';best=Math.max(best,Math.floor(distance));wallet+=runCoins;localStorage.setItem('fwCoins',wallet);localStorage.setItem('fwBest',best);$('best').textContent=String(best).padStart(4,'0');$('finalDistance').textContent=Math.floor(distance)+' m';$('finalCoins').textContent=runCoins;$('finalBest').textContent=best+' m';setOverlay('overScreen');$('mobileControls').style.display='none';beep(110,.35,'sawtooth');}
function action(a){if(state!=='playing')return;if(a==='left')targetLane=Math.max(-1,targetLane-1);if(a==='right')targetLane=Math.min(1,targetLane+1);if(a==='jump'&&playerY<.03&&sliding<=0){vy=8.3;beep(440,.07)}if(a==='slide'&&playerY<.18){sliding=.68;beep(280,.06)}}
function spawnBurst(x,y,color){for(let i=0;i<8;i++)particles.push({x,y,vx:(Math.random()-.5)*95,vy:(Math.random()-.8)*90,life:.8,size:2+Math.random()*3,color})}
function update(dt){if(state!=='playing')return;dt=Math.min(dt,.035);speed=Math.min(28,17+distance*.013);world+=speed*dt;distance+=speed*dt*.72;lane+=(targetLane-lane)*Math.min(1,dt*13);if(playerY>0||vy>0){playerY+=vy*dt;vy-=20*dt;if(playerY<0){playerY=0;vy=0}}if(sliding>0)sliding=Math.max(0,sliding-dt);spawnTimer-=dt;if(spawnTimer<=0){spawnPattern();spawnTimer=Math.max(.65,1.15-distance*.0007)+Math.random()*.35}
 for(let o of objects){let old=o.z;o.z-=speed*dt;if(o.kind==='coin'&&old>1.3&&o.z<=1.3&&Math.abs(lane-o.lane)<.62){o.collected=true;runCoins++;wallet++;localStorage.setItem('fwCoins',wallet);let p=project(o.lane*2.08,1.1,o.z);spawnBurst(p.x,p.y,'#dcff47');beep(760+Math.random()*200,.075);}
  if(o.kind==='obstacle'&&!o.hit&&old>1.35&&o.z<=1.35&&Math.abs(lane-o.lane)<.58){let safe=o.type==='barrier'?playerY>.78:o.type==='beam'?sliding>.14:false;if(!safe){o.hit=true;shake=12;finishRun();break}}
 }
 objects=objects.filter(o=>o.z>-4&&!o.collected);for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=100*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*34);
 $('distance').textContent=String(Math.floor(distance)).padStart(4,'0');$('coins').textContent=String(runCoins);$('speed').textContent=(speed/17).toFixed(1)+'x';}

