addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Escape','a','d','w','s'].includes(e.key))e.preventDefault();if(e.key==='Escape'){if($('shop').classList.contains('open'))$('shop').classList.remove('open');else pauseRun();return}if(e.key===' '){if(state==='playing'||state==='paused')pauseRun();return}if(e.key==='ArrowLeft'||e.key==='a')action('left');if(e.key==='ArrowRight'||e.key==='d')action('right');if(e.key==='ArrowUp'||e.key==='w')action('jump');if(e.key==='ArrowDown'||e.key==='s')action('slide')});
document.querySelectorAll('.mobileControls button').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action)}));let touch=null;addEventListener('touchstart',e=>{if(e.target.closest('button')||e.target.closest('.shop'))return;let t=e.changedTouches[0];touch={x:t.clientX,y:t.clientY}}, {passive:true});addEventListener('touchend',e=>{if(!touch)return;let t=e.changedTouches[0],dx=t.clientX-touch.x,dy=t.clientY-touch.y;if(Math.max(Math.abs(dx),Math.abs(dy))>25){if(Math.abs(dx)>Math.abs(dy))action(dx>0?'right':'left');else action(dy<0?'jump':'slide')}touch=null},{passive:true});
